import { SHARE_IMAGE_URL, SLOGO } from '../config';
import { getAppBootstrapConfig } from './appMode';

export function getConfiguredShareTitle() {
	const config = getAppBootstrapConfig();
	return String(config.shareTitle || SLOGO).trim() || SLOGO;
}

export function getConfiguredShareImageUrl() {
	const config = getAppBootstrapConfig();
	return String(config.shareImageUrl || SHARE_IMAGE_URL).trim() || SHARE_IMAGE_URL;
}

export function getCurrentPageSharePath() {
	const pages = typeof getCurrentPages === 'function' ? getCurrentPages() : [];
	const currentPage = pages[pages.length - 1] || {};
	const route = String(currentPage.route || '').replace(/^\//, '');
	const options = currentPage.options && typeof currentPage.options === 'object'
		? currentPage.options
		: {};
	const query = Object.keys(options)
		.filter((key) => options[key] !== undefined && options[key] !== null && options[key] !== '')
		.map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(options[key])}`)
		.join('&');

	return route ? `/${route}${query ? `?${query}` : ''}` : '/pages/meet/index';
}

export function buildShareAppMessage(path) {
	return {
		title: getConfiguredShareTitle(),
		path,
		imageUrl: getConfiguredShareImageUrl()
	};
}
